const grades = ['小一', '小二', '小三', '小四', '小五', '小六'];
const subjects = ['英文', '數學'];
const qTypes = ['標準題型', '觀念拆解', '錯題診斷'];

const gradeEnglish = {
  '小一': '康軒Wonder World', '小二': '康軒Wonder World',
  '小三': '康軒Wonder World', '小四': '康軒Wonder World',
  '小五': '何嘉仁Super Fun',  '小六': '康軒Wonder World',
};
const gradeMath = {
  '小一': '康軒', '小二': '翰林', '小三': '康軒',
  '小四': '南一', '小五': '康軒', '小六': '南一',
};

const now = new Date();
const month = now.getMonth();
const semester = (month >= 7 || month <= 0) ? '上學期' : '下學期';
const acadYear = now.getFullYear() - 1911 + (month >= 7 ? 0 : -1);
const acadYearLabel = `${acadYear}學年度`;

const nextMonthDate = new Date(now.getFullYear(), now.getMonth() + 1, 1);
const yearMonth = `${nextMonthDate.getFullYear()}${String(nextMonthDate.getMonth() + 1).padStart(2, '0')}`;

function getAcademicWeek(satDate) {
  const y = satDate.getFullYear();
  const m = satDate.getMonth();
  const acadStart = m >= 7 ? new Date(y, 7, 1) : new Date(y - 1, 7, 1);
  const dow = acadStart.getDay();
  const dToSat = dow === 6 ? 0 : (6 - dow);
  const firstSat = new Date(acadStart.getTime() + dToSat * 86400000);
  const diffDays = Math.round((satDate.getTime() - firstSat.getTime()) / 86400000);
  return Math.floor(diffDays / 7) + 1;
}

const saturdays = [];
for (let d = new Date(nextMonthDate); saturdays.length < 6; d.setDate(d.getDate() + 1)) {
  if (d.getDay() === 6) {
    const sat = new Date(d);
    saturdays.push({
      iso: sat.toISOString().slice(0, 10),
      weekNum: getAcademicWeek(sat)
    });
  }
}

const typeAbbr = { '標準題型': '標', '觀念拆解': '觀', '錯題診斷': '錯' };
const gradeCode = { '小一': '1', '小二': '2', '小三': '3', '小四': '4', '小五': '5', '小六': '6' };
const subjectCode = { '英文': 'en', '數學': 'ma' };

const tasks = [];
for (const grade of grades) {
  for (const subject of subjects) {
    for (const qType of qTypes) {
      const curriculum = subject === '英文' ? gradeEnglish[grade] : gradeMath[grade];
      tasks.push({ json: {
        grade, subject, curriculum, semester, acadYear: acadYearLabel, qType,
        typeAbbr: typeAbbr[qType], gradeCode: gradeCode[grade],
        subjectCode: subjectCode[subject], yearMonth, saturdays, count: saturdays.length
      }});
    }
  }
}
return tasks;

const openrouterResp = $input.item.json;
const task = $('建立出題任務清單').item.json;

const { grade, subject, curriculum, semester, acadYear, qType, typeAbbr,
        gradeCode, subjectCode, yearMonth, saturdays } = task;

let raw = (openrouterResp.choices?.[0]?.message?.content) || '';
raw = raw.replace(/```json/g, '').replace(/```/g, '').trim();

let questions = [];
try {
  const first = raw.indexOf('[');
  const last = raw.lastIndexOf(']');
  if (first !== -1 && last > first) {
    questions = JSON.parse(raw.slice(first, last + 1));
  }
} catch (e) {
  console.error('Parse error:', grade, subject, qType, e.message);
  return [];
}

const results = [];
for (let i = 0; i < Math.min(questions.length, saturdays.length); i++) {
  const q = questions[i];
  if (!q) continue;
  const { iso: publishDate, weekNum } = saturdays[i];
  const questionId = `${subjectCode}-${gradeCode}-${typeAbbr}-w${weekNum}-${yearMonth}-001`;
  results.push({ json: {
    questionId, grade, subject, curriculum, semester, acadYear, qType,
    chapter: q.chapter || '',
    question: q.question || '',
    optionA: q.optionA || '',
    optionB: q.optionB || '',
    optionC: q.optionC || '',
    optionD: q.optionD || '',
    answer: q.answer || 'A',
    concept: q.concept || '',
    mistake: q.mistake || '',
    hint: q.hint || '',
    publishDate,
    weekNum
  }});
}
return results;
